#[test]
fn test_bhv_mocking_002_group_trait_lists_exactly_the_public_operations_of_the_class() {
    let (listed, declared) = read_group("src/api/pet_api.rs", "PetApiTrait");
    let mut listed = listed;
    let mut declared = declared;
    listed.sort();
    declared.sort();
    assert_eq!(listed, declared);
    let (listed, declared) = read_group("src/api/problems_api.rs", "ProblemsApiTrait");
    let mut listed = listed;
    let mut declared = declared;
    listed.sort();
    declared.sort();
    assert_eq!(listed, declared);
    let (listed, declared) = read_group("src/api/store_api.rs", "StoreApiTrait");
    let mut listed = listed;
    let mut declared = declared;
    listed.sort();
    declared.sort();
    assert_eq!(listed, declared);
}

fn exposes_every_group_and_closes<C: ClientTrait>(client: &C) -> bool {
    let _ = client.pet();
    let _ = client.problems();
    let _ = client.store();
    client.close();
    client.is_closed()
}

#[test]
fn test_bhv_mocking_007_client_trait_exposes_every_group_typed_as_its_trait_and_close() {
    let authenticator = BearerAuthenticator::new("/api/v3", "test-token").unwrap();
    let client = Client::new(Box::new(authenticator), None);

    assert!(exposes_every_group_and_closes(&client));
}

struct FakeClient {
    closed: std::sync::atomic::AtomicUsize,
    pet: FakePetApi,
    problems: FakeProblemsApi,
    store: FakeStoreApi,
}

impl ClientTrait for FakeClient {
    type Pet = FakePetApi;
    type Problems = FakeProblemsApi;
    type Store = FakeStoreApi;

    fn pet(&self) -> &Self::Pet {
        &self.pet
    }

    fn problems(&self) -> &Self::Problems {
        &self.problems
    }

    fn store(&self) -> &Self::Store {
        &self.store
    }

    fn close(&self) {
        self.closed
            .fetch_add(1, std::sync::atomic::Ordering::SeqCst);
    }

    fn is_closed(&self) -> bool {
        self.closed.load(std::sync::atomic::Ordering::SeqCst) > 0
    }
}

#[test]
fn test_bhv_mocking_008_client_built_from_fakes_never_connects_and_closes_without_error() {
    let fake = FakeClient {
        closed: std::sync::atomic::AtomicUsize::new(0),
        pet: FakePetApi::new(),
        problems: FakeProblemsApi::new(),
        store: FakeStoreApi::new(),
    };

    assert!(exposes_every_group_and_closes(&fake));
    fake.close();

    assert_eq!(fake.closed.load(std::sync::atomic::Ordering::SeqCst), 2);
}

/* The hook set on the client reaches every API group. */
#[tokio::test]
async fn test_bhv_langrust_086_the_call_hook_reaches_every_api_group() {
    use petstore::{CallHook, CallInfo, CallObserver};
    use std::collections::HashMap;
    use std::sync::{Arc, Mutex};

    struct Counting(Arc<Mutex<Vec<String>>>);
    impl CallHook for Counting {
        fn start(
            &self,
            info: &CallInfo,
            _headers: &mut HashMap<String, String>,
        ) -> Option<Box<dyn CallObserver>> {
            self.0.lock().unwrap().push(info.operation_id.clone());
            None
        }
    }
    let seen = Arc::new(Mutex::new(Vec::new()));
    let transport = TransportOptionsBuilder::new()
        .max_retries(0)
        .build()
        .expect("valid transport options");
    let client = Client::new(
        Box::new(BearerAuthenticator::new("http://127.0.0.1:1", "token").unwrap()),
        Some(transport),
    )
    .with_call_hook(Arc::new(Counting(seen.clone())));

    let _ = client.pet.delete_pet(1, None).await;
    let _ = client.store.delete_order(1, None).await;

    assert_eq!(
        vec!["deletePet".to_string(), "deleteOrder".to_string()],
        *seen.lock().unwrap()
    );
}

/* F826: a client built without a host or token takes both from the environment. */
#[test]
fn test_bhv_misc_187_a_client_built_without_host_or_token_takes_both_from_the_environment() {
    std::env::set_var("PETSTORE_BASE_URL", "https://env.example.com");
    std::env::set_var("PETSTORE_ACCESS_TOKEN", "env-token");
    let built = Client::with_token(None, None, None);
    std::env::remove_var("PETSTORE_BASE_URL");
    std::env::remove_var("PETSTORE_ACCESS_TOKEN");
    built.expect("the environment supplies both the host and the token");
}
